// Automatically selected signature traits for the offensive style model.
// Five traits per player from 31 behavioral features: league extremeness +
// archetype deviation, with correlation-diversity so traits don't repeat.

export type SignatureTrait = {
  rank: number
  featureIndex: number
  key: string
  label: string
  family: string
  percentile: number
  zScore: number
  centroidZ: number
  archetypeDeltaZ: number
  baseRelevance: number
  adjustedRelevance: number
  direction: 'high' | 'low'
}

export type UniqueStatsPlayer = {
  playerId: string
  playerName: string
  cluster: number
  touches: number
  signatureTraits: SignatureTrait[]
}

export type UniqueStats = {
  seasonYear: number
  playerCount: number
  traitsPerPlayer: number
  methodology: {
    baseRelevance: string
    selection: string
  }
  players: UniqueStatsPlayer[]
}

